package com.example.logtracing.config;

import com.example.logtracing.dto.TelemetryPayload;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.common.serialization.StringSerializer;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.core.DefaultKafkaProducerFactory;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.core.ProducerFactory;
import org.springframework.kafka.support.serializer.JsonSerializer;

import java.util.HashMap;
import java.util.Map;

@Configuration
public class KafkaProducerConfig {

    @Value("${spring.kafka.bootstrap-servers:localhost:9092}")
    private String bootstrapServers;

    @Bean
    public ProducerFactory<String, TelemetryPayload> producerFactory() {
        Map<String, Object> config = new HashMap<>();
        config.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, bootstrapServers);
        config.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class);
        config.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, JsonSerializer.class);
        return new DefaultKafkaProducerFactory<>(config);
    }

    @Bean
    public KafkaTemplate<String, TelemetryPayload> kafkaTemplate() {
        return new KafkaTemplate<>(producerFactory());
    }
}

package com.example.logtracing.consumer;

import com.example.logtracing.dto.TelemetryPayload;
import com.example.logtracing.entity.Span;
import com.example.logtracing.entity.Trace;
import com.example.logtracing.repository.SpanRepository;
import com.example.logtracing.repository.TraceRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.support.KafkaHeaders;
import org.springframework.messaging.handler.annotation.Header;
import org.springframework.messaging.handler.annotation.Payload;
import org.springframework.stereotype.Service;

@Service
public class TelemetryKafkaConsumer {

    private static final Logger logger = LoggerFactory.getLogger(TelemetryKafkaConsumer.class);

    @Autowired
    private TraceRepository traceRepository;

    @Autowired
    private SpanRepository spanRepository;

    @KafkaListener(topics = "app-telemetry-log", groupId = "telemetry-consumer-group")
    public void consumeTelemetryData(
            @Payload TelemetryPayload payload,
            @Header(KafkaHeaders.RECEIVED_TOPIC) String topic,
            @Header(KafkaHeaders.RECEIVED_PARTITION) int partition,
            @Header(KafkaHeaders.OFFSET) long offset) {

        try {
            logger.info("Received telemetry message from topic: {}, partition: {}, offset: {}", 
                       topic, partition, offset);
            logger.info("Payload: {}", payload);

            // Validate payload
            if (payload.getTraceId() == null || payload.getSpanId() == null) {
                logger.error("Invalid payload: traceId or spanId is null");
                return;
            }

            // Find or create Trace
            Trace trace = traceRepository.findByTraceId(payload.getTraceId());
            if (trace == null) {
                trace = new Trace();
                trace.setTraceId(payload.getTraceId());
                trace.setSource("kafka");
                trace = traceRepository.save(trace);
                logger.info("Created new trace with traceId: {}", payload.getTraceId());
            } else {
                logger.info("Found existing trace with traceId: {}", payload.getTraceId());
            }

            // Create and save Span
            Span span = new Span();
            span.setSpanId(payload.getSpanId());
            span.setParentSpanId(payload.getParentSpanId());
            span.setMethodName(payload.getDetails());
            span.setCaller(payload.getStatus());
            span.setStartTime(payload.getTimestamp());
            span.setTrace(trace);
            spanRepository.save(span);

            logger.info("Successfully saved span with spanId: {} for traceId: {}", 
                       payload.getSpanId(), payload.getTraceId());

        } catch (Exception e) {
            logger.error("Error processing telemetry data from Kafka: {}", e.getMessage(), e);
            // Depending on requirements, you might want to:
            // - Send to a dead-letter queue
            // - Retry with exponential backoff
            // - Just log and continue (current behavior)
        }
    }
}

package com.example.logtracing.controller;

import org.springframework.http.ResponseEntity;
import org.springframework.beans.factory.annotation.Autowired;
import com.example.logtracing.entity.Trace;
import com.example.logtracing.entity.Span;
import com.example.logtracing.repository.TraceRepository;
import com.example.logtracing.repository.SpanRepository;

import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/log")
@CrossOrigin("*")
public class LogController {
    @Autowired
    private TraceRepository traceRepository;
    @Autowired
    private SpanRepository spanRepository;
    @PostMapping("/trace-span")
    public ResponseEntity<String> receiveTraceSpan(@RequestBody LogPayload payload) {
        // Find or create Trace
        Trace trace = traceRepository.findByTraceId(payload.traceId);
        if (trace == null) {
            trace = new Trace();
            trace.setTraceId(payload.traceId);
            trace.setSource("api"); // or set from payload if available
            trace = traceRepository.save(trace);
        }

        // Create and save Span
        Span span = new Span();
            span.setSpanId(payload.spanId);
            span.setParentSpanId(payload.parentSpanId);
            span.setMethodName(payload.details); // or set actual method name if available
            span.setCaller(payload.status); // or set actual caller if available
            span.setStartTime(payload.timestamp);
        span.setTrace(trace);
        spanRepository.save(span);

        return ResponseEntity.ok("Saved to DB");
    }

    public static class LogPayload {
        public String traceId;
        public String spanId;
        public String parentSpanId;
        public String status; // "error" or "success"
        public String details;
        public Long timestamp; // epoch millis
    }

    @PostMapping("/spans-by-trace")
    public ResponseEntity<?> getSpansByTrace(@RequestBody TraceQuery query) {
        // Find trace
        Trace trace = traceRepository.findByTraceId(query.traceId);
        if (trace == null || trace.getSpans() == null || trace.getSpans().isEmpty()) {
            // Default sample response
            return ResponseEntity.ok(java.util.Arrays.asList(
                new SpanSample(1L, "span-001", null, "ServiceA.processRequest", "success", 1701860000000L, null, new TraceSample(1L, "trace-123", "api")),
                new SpanSample(2L, "span-002", "span-001", "ServiceB.handleEvent", "success", 1701860000500L, null, new TraceSample(1L, "trace-123", "api")),
                new SpanSample(3L, "span-003", "span-002", "ServiceC.finalize", "error", 1701860001000L, null, new TraceSample(1L, "trace-123", "api"))
            ));
        }
        // Get spans, order by startTime
        var spans = trace.getSpans();
        spans.sort((a, b) -> Long.compare(
            a.getStartTime() != null ? a.getStartTime() : 0L,
            b.getStartTime() != null ? b.getStartTime() : 0L));
        return ResponseEntity.ok(spans);

    }

    // Sample DTOs for default response
    static class SpanSample {
        public Long id;
        public String spanId;
        public String parentSpanId;
        public String methodName;
        public String caller;
        public Long startTime;
        public Long endTime;
        public TraceSample trace;
        public SpanSample(Long id, String spanId, String parentSpanId, String methodName, String caller, Long startTime, Long endTime, TraceSample trace) {
            this.id = id;
            this.spanId = spanId;
            this.parentSpanId = parentSpanId;
            this.methodName = methodName;
            this.caller = caller;
            this.startTime = startTime;
            this.endTime = endTime;
            this.trace = trace;
        }
    }
    static class TraceSample {
        public Long id;
        public String traceId;
        public String source;
        public TraceSample(Long id, String traceId, String source) {
            this.id = id;
            this.traceId = traceId;
            this.source = source;
        }
    }
    static class TraceQuery {
        public String traceId;
    }
}

package com.example.logtracing.controller;

import org.springframework.http.ResponseEntity;
import org.springframework.beans.factory.annotation.Autowired;
import com.example.logtracing.entity.Trace;
import com.example.logtracing.entity.Span;
import com.example.logtracing.repository.TraceRepository;
import com.example.logtracing.repository.SpanRepository;
import com.example.logtracing.service.TelemetryProducerService;
import com.example.logtracing.dto.TelemetryPayload;

import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/log")
@CrossOrigin("*")
public class LogController {
    @Autowired
    private TraceRepository traceRepository;
    @Autowired
    private SpanRepository spanRepository;
    @Autowired
    private TelemetryProducerService telemetryProducerService;

    @PostMapping("/trace-span")
    public ResponseEntity<String> receiveTraceSpan(@RequestBody LogPayload payload) {
        // Find or create Trace
        Trace trace = traceRepository.findByTraceId(payload.traceId);
        if (trace == null) {
            trace = new Trace();
            trace.setTraceId(payload.traceId);
            trace.setSource("api"); // or set from payload if available
            trace = traceRepository.save(trace);
        }

        // Create and save Span
        Span span = new Span();
            span.setSpanId(payload.spanId);
            span.setParentSpanId(payload.parentSpanId);
            span.setMethodName(payload.details); // or set actual method name if available
            span.setCaller(payload.status); // or set actual caller if available
            span.setStartTime(payload.timestamp);
        span.setTrace(trace);
        spanRepository.save(span);

        return ResponseEntity.ok("Saved to DB");
    }

    public static class LogPayload {
        public String traceId;
        public String spanId;
        public String parentSpanId;
        public String status; // "error" or "success"
        public String details;
        public Long timestamp; // epoch millis
    }

    @PostMapping("/publish-to-kafka")
    public ResponseEntity<String> publishToKafka(@RequestBody LogPayload payload) {
        try {
            TelemetryPayload telemetryPayload = new TelemetryPayload(
                payload.traceId,
                payload.spanId,
                payload.parentSpanId,
                payload.status,
                payload.details,
                payload.timestamp
            );
            telemetryProducerService.sendTelemetryData(telemetryPayload);
            return ResponseEntity.ok("Message sent to Kafka topic: app-telemetry-log");
        } catch (Exception e) {
            return ResponseEntity.status(500).body("Failed to send message to Kafka: " + e.getMessage());
        }
    }

    @PostMapping("/spans-by-trace")
    public ResponseEntity<?> getSpansByTrace(@RequestBody TraceQuery query) {
        // Find trace
        Trace trace = traceRepository.findByTraceId(query.traceId);
        if (trace == null || trace.getSpans() == null || trace.getSpans().isEmpty()) {
            // Default sample response
            return ResponseEntity.ok(java.util.Arrays.asList(
                new SpanSample(1L, "span-001", null, "ServiceA.processRequest", "success", 1701860000000L, null, new TraceSample(1L, "trace-123", "api")),
                new SpanSample(2L, "span-002", "span-001", "ServiceB.handleEvent", "success", 1701860000500L, null, new TraceSample(1L, "trace-123", "api")),
                new SpanSample(3L, "span-003", "span-002", "ServiceC.finalize", "error", 1701860001000L, null, new TraceSample(1L, "trace-123", "api"))
            ));
        }
        // Get spans, order by startTime
        var spans = trace.getSpans();
        spans.sort((a, b) -> Long.compare(
            a.getStartTime() != null ? a.getStartTime() : 0L,
            b.getStartTime() != null ? b.getStartTime() : 0L));
        return ResponseEntity.ok(spans);

    }

    // Sample DTOs for default response
    static class SpanSample {
        public Long id;
        public String spanId;
        public String parentSpanId;
        public String methodName;
        public String caller;
        public Long startTime;
        public Long endTime;
        public TraceSample trace;
        public SpanSample(Long id, String spanId, String parentSpanId, String methodName, String caller, Long startTime, Long endTime, TraceSample trace) {
            this.id = id;
            this.spanId = spanId;
            this.parentSpanId = parentSpanId;
            this.methodName = methodName;
            this.caller = caller;
            this.startTime = startTime;
            this.endTime = endTime;
            this.trace = trace;
        }
    }
    static class TraceSample {
        public Long id;
        public String traceId;
        public String source;
        public TraceSample(Long id, String traceId, String source) {
            this.id = id;
            this.traceId = traceId;
            this.source = source;
        }
    }
    static class TraceQuery {
        public String traceId;
    }
}

package com.example.logtracing.dto;

import com.fasterxml.jackson.annotation.JsonProperty;

public class TelemetryPayload {
    @JsonProperty("traceId")
    private String traceId;

    @JsonProperty("spanId")
    private String spanId;

    @JsonProperty("parentSpanId")
    private String parentSpanId;

    @JsonProperty("status")
    private String status; // "error" or "success"

    @JsonProperty("details")
    private String details;

    @JsonProperty("timestamp")
    private Long timestamp; // epoch millis

    // Default constructor for Jackson
    public TelemetryPayload() {
    }

    public TelemetryPayload(String traceId, String spanId, String parentSpanId, String status, String details, Long timestamp) {
        this.traceId = traceId;
        this.spanId = spanId;
        this.parentSpanId = parentSpanId;
        this.status = status;
        this.details = details;
        this.timestamp = timestamp;
    }

    // Getters and setters
    public String getTraceId() {
        return traceId;
    }

    public void setTraceId(String traceId) {
        this.traceId = traceId;
    }

    public String getSpanId() {
        return spanId;
    }

    public void setSpanId(String spanId) {
        this.spanId = spanId;
    }

    public String getParentSpanId() {
        return parentSpanId;
    }

    public void setParentSpanId(String parentSpanId) {
        this.parentSpanId = parentSpanId;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public String getDetails() {
        return details;
    }

    public void setDetails(String details) {
        this.details = details;
    }

    public Long getTimestamp() {
        return timestamp;
    }

    public void setTimestamp(Long timestamp) {
        this.timestamp = timestamp;
    }

    @Override
    public String toString() {
        return "TelemetryPayload{" +
                "traceId='" + traceId + '\'' +
                ", spanId='" + spanId + '\'' +
                ", parentSpanId='" + parentSpanId + '\'' +
                ", status='" + status + '\'' +
                ", details='" + details + '\'' +
                ", timestamp=" + timestamp +
                '}';
    }
}
